:root {
    --bg-primary: #0F0F0F;
    --bg-secondary: #1A080C;
    --brand-maroon: #2C0E18;
    --brand-maroon-deep: #4A0E1F;
    --accent-gold: #D4AF37;
    --accent-gold-soft: #F3E5AB;
    --accent-ivory: #FFFFF0;
    --text-primary: #FFFFF0;
    --text-secondary: #C8C8C8;
    --glass-border: rgba(255, 255, 255, 0.1);
    --glass-bg: rgba(26, 8, 12, 0.4);
}

html, body {
    margin: 0;
    padding: 0;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: 'Outfit', sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: auto; /* Lenis handles smooth scroll */
}

::selection {
    background: var(--accent-gold);
    color: #0F0F0F;
}

/* Custom Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #0F0F0F; }
::-webkit-scrollbar-thumb { background: linear-gradient(180deg, #2C0E18, #D4AF37); border-radius: 8px; }

/* Typography helpers */
.font-serif-display { font-family: 'Cormorant Garamond', serif; }
.font-sans-display { font-family: 'Outfit', sans-serif; }
.font-devanagari { font-family: 'Tiro Devanagari Hindi', serif; }

/* Glassmorphic surface */
.glass {
    background: rgba(26, 8, 12, 0.35);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 240, 0.1);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

.glass-strong {
    background: rgba(15, 15, 15, 0.6);
    backdrop-filter: blur(28px);
    -webkit-backdrop-filter: blur(28px);
    border: 1px solid rgba(212, 175, 55, 0.18);
}

/* Gold gradient text */
.text-gold-gradient {
    background: linear-gradient(135deg, #F3E5AB 0%, #D4AF37 45%, #8B7322 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* Animated grain overlay */
.grain::before {
    content: "";
    position: fixed; inset: 0;
    pointer-events: none;
    z-index: 1;
    opacity: 0.06;
    background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
}

/* Marquee */
@keyframes marquee {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
}
.marquee-track { animation: marquee 40s linear infinite; }

/* Underline link */
.link-underline {
    position: relative;
}
.link-underline::after {
    content: "";
    position: absolute;
    left: 0; bottom: -4px;
    height: 1px; width: 0;
    background: #D4AF37;
    transition: width 400ms ease;
}
.link-underline:hover::after { width: 100%; }

/* Hide horizontal overflow caused by motion translates */
html, body { overflow-x: hidden; }

/* Lenis recommended */
html.lenis, html.lenis body { height: auto; }
.lenis.lenis-smooth { scroll-behavior: auto !important; }
.lenis.lenis-smooth [data-lenis-prevent] { overscroll-behavior: contain; }
.lenis.lenis-stopped { overflow: hidden; }
